    assert(pre.pointer_ordering());
    assert forall |n| 0 <= n < pre.num_replicas ==> pre.local_versions[n] <= pre.tail by {
        if 0 <= n < pre.num_replicas {
            assert(pre.local_versions.contains_key(n));
            assert(pre.pointer_ordering());
        }
    };
    assert forall |n| 0 <= n < pre.num_replicas ==> pre.tail <= pre.local_versions[n] + pre.buffer_size by {
        if 0 <= n < pre.num_replicas {
            assert(pre.local_versions.contains_key(n));
            assert(pre.pointer_ordering());
        }
    };
    assert forall |n| 0 <= n < pre.num_replicas ==> post.head <= post.local_versions[n] by {
        if 0 <= n < pre.num_replicas {
            assert(pre.local_versions.contains_key(n));
            assert(pre.combiner[node_id].is_AdvancingHead());
            assert(pre.combiner[node_id].get_AdvancingHead_min_local_version() <= pre.local_versions[n]);
        }
    };
    assert(pre.combiner[node_id].is_AdvancingHead());
    assert(post.head == pre.combiner[node_id].get_AdvancingHead_min_local_version());
    assert(post.tail == pre.tail);
